#!/bin/sh
# EduGuard server add-on entrypoint.
#
# Seeds /data/server.toml on first run (the only persistent volume — config,
# SQLite database and screenshots all live under /data), then hands off to
# the server. An empty admin_password is generated by the server itself and
# printed to the log together with the first-run enrollment token.
set -eu

ARCH=$(uname -m)
BIN="/opt/eduguard/bin/${ARCH}/eduguard-server"
if [ ! -x "$BIN" ]; then
  echo "[eduguard] unsupported architecture '${ARCH}' (supported: x86_64, aarch64)" >&2
  exit 1
fi

# Flat reader for the add-on options JSON written by the Supervisor UI.
opt() {
  [ -f /data/options.json ] || return 0
  jq -r --arg k "$1" '.[$k] // empty' /data/options.json 2>/dev/null || true
}
# Escape a value for a double-quoted TOML string.
toml_str() { printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'; }

mkdir -p /data

if [ ! -f /data/server.toml ]; then
  pw=$(opt admin_password)
  school=$(opt school_name)
  [ -n "$school" ] || school="EduGuard School"
  cat > /data/server.toml <<EOF
listen = "0.0.0.0:8443"
data_dir = "/data"
admin_username = "admin"
admin_password = "$(toml_str "$pw")"
school_name = "$(toml_str "$school")"
session_ttl_secs = 43200
screenshot_retention_days = 30
event_retention_days = 365
offline_after_secs = 20
EOF
  echo "[eduguard] first run: wrote /data/server.toml"
fi

# Options only apply on first run; later changes go through the console or by
# deleting /data/server.toml (the database in /data is preserved).
exec "$BIN" --config /data/server.toml serve
